#include <memory>
#include <string>
#include <vector>
#include <functional>
#include <iostream>
#include <cstring>

namespace email_service {

class AttachmentBuffer {
public:
    AttachmentBuffer(size_t capacity) : capacity_(capacity), size_(0) {
        data_ = new char[capacity];
    }
    ~AttachmentBuffer() { delete[] data_; data_ = nullptr; }

    AttachmentBuffer(const AttachmentBuffer&) = delete;
    AttachmentBuffer& operator=(const AttachmentBuffer&) = delete;

    AttachmentBuffer(AttachmentBuffer&& other) noexcept 
        : data_(other.data_), capacity_(other.capacity_), size_(other.size_) {
        other.data_ = nullptr;
        other.capacity_ = 0;
        other.size_ = 0;
    }

    bool append(const char* src, size_t len) {
        if (size_ + len > capacity_) return false;
        memcpy(data_ + size_, src, len);
        size_ += len;
        return true;
    }

    const char* data() const { return data_; }
    size_t size() const { return size_; }
    size_t capacity() const { return capacity_; }

private:
    char* data_;
    size_t capacity_;
    size_t size_;
};

class MimeEncoder {
public:
    using EncodingCallback = std::function<void(const char*, size_t)>;

    MimeEncoder() : pending_buffer_(nullptr), pending_size_(0) {}

    void set_output_callback(EncodingCallback cb) { callback_ = std::move(cb); }

    void encode_chunk(const char* data, size_t len) {
        pending_buffer_ = data;
        pending_size_ = len;
    }

    void flush() {
        if (pending_buffer_ && callback_) {
            callback_(pending_buffer_, pending_size_);
        }
        pending_buffer_ = nullptr;
        pending_size_ = 0;
    }

private:
    EncodingCallback callback_;
    const char* pending_buffer_;
    size_t pending_size_;
};

class AttachmentProcessor {
public:
    struct ProcessedAttachment {
        std::string encoded_content;
        std::string mime_type;
        std::string filename;
    };

    AttachmentProcessor() {}

    ProcessedAttachment process(AttachmentBuffer&& upload_buf, 
                                const std::string& filename,
                                const std::string& mime_type) {
        ProcessedAttachment result;
        result.filename = filename;
        result.mime_type = mime_type;

        encoder_.set_output_callback([&result](const char* data, size_t len) {
            result.encoded_content.assign(data, len);
        });

        // Stage 1: validate and potentially re-buffer first
        auto validated = validate_and_normalize(std::move(upload_buf), mime_type);

        // Stage 2: encode from the validated buffer (which owns the data)
        encoder_.encode_chunk(validated.data(), validated.size());

        // Stage 3: flush pending encoding (uses pointer from validated buffer)
        encoder_.flush();

        return result;
    }

private:
    MimeEncoder encoder_;

    AttachmentBuffer validate_and_normalize(AttachmentBuffer&& buf, 
                                            const std::string& mime_type) {
        if (mime_type.find("image/") == 0) {
            // For images, create a normalized copy with header validation
            AttachmentBuffer normalized(buf.size() + 64);
            // Simulate normalization: copy with potential header fixup
            if (buf.data() && buf.size() > 0) {
                normalized.append(buf.data(), buf.size());
            }
            return normalized;
        }
        return std::move(buf);
    }
};

class EmailComposer {
public:
    struct Email {
        std::string from;
        std::string to;
        std::string subject;
        std::string body;
        std::vector<AttachmentProcessor::ProcessedAttachment> attachments;
    };

    Email compose(const std::string& from, const std::string& to,
                  const std::string& subject, const std::string& body,
                  std::vector<std::pair<std::string, std::string>>& upload_metadata,
                  std::vector<AttachmentBuffer>& upload_buffers) {
        Email email;
        email.from = from;
        email.to = to;
        email.subject = subject;
        email.body = body;

        AttachmentProcessor processor;
        // Only process as many attachments as we have matching metadata for,
        // preventing an out-of-bounds read into upload_metadata.
        size_t count = std::min(upload_buffers.size(), upload_metadata.size());
        for (size_t i = 0; i < count; ++i) {
            auto& meta = upload_metadata[i];
            auto attachment = processor.process(
                std::move(upload_buffers[i]),
                meta.first,   // filename
                meta.second   // mime_type
            );
            email.attachments.push_back(std::move(attachment));
        }

        return email;
    }
};

} // namespace email_service

int main() {
    using namespace email_service;

    // Simulate user upload
    AttachmentBuffer upload(1024);
    const char* fake_png = "\x89PNG\r\n\x1a\n fake image data here";
    upload.append(fake_png, strlen(fake_png));

    std::vector<AttachmentBuffer> buffers;
    buffers.push_back(std::move(upload));

    std::vector<std::pair<std::string, std::string>> metadata;
    metadata.push_back({"photo.png", "image/png"});

    EmailComposer composer;
    auto email = composer.compose(
        "user@example.com", "recipient@example.com",
        "Hello", "Please see attached.",
        metadata, buffers
    );

    std::cout << "Email composed with " << email.attachments.size() 
              << " attachment(s)" << std::endl;
    if (!email.attachments.empty()) {
        std::cout << "Attachment content length: " 
                  << email.attachments[0].encoded_content.size() << std::endl;
    }

    return 0;
}
